parameters.jsCode:
const payload = $json.body.payload || $json.body;
const invitee = payload.invitee || {};
const event = payload.scheduled_event || {};

// Parse Questions and Answers
const questions = invitee.questions_and_answers || [];
const notes = questions.map(q => `${q.question}: ${q.answer}`).join('\n');

return {
  email: invitee.email,
  name: invitee.name,
  start_time: event.start_time || payload.start_time || 'Check Calendly',
  notes: notes || 'No specific questions answered.',
  event_name: event.name || (payload.event_type ? payload.event_type.name : 'Meeting Booked')
};

